"use server";

// Generated by philote from component SwipeDeck's calls. Do not edit.
import * as api from "@/lib/api";
import { message } from "@/lib/form";
import type { Swipe, Match } from "@/lib/types";
import { needViewer } from "@/lib/viewer";

// SwipeResult is what a call to swipe did: what it made, or the
// error to show.
export type SwipeResult = { ok: true; value: { swipe: Swipe; match: Match | null } } | { ok: false; error: string };

// swipe calls the swipe endpoint as the viewer.
export async function swipe(input: { target: string; liked: boolean }): Promise<SwipeResult> {
    const viewer = await needViewer();
    const result = await api.swipe({ horse: viewer.id, target: input.target, liked: input.liked });
    return result.ok ? { ok: true, value: result.value } : { ok: false, error: message(result.error) };
}
